96	  fn call_macro(&self, src: String, export: String, call: CallExpr) -> Result<Expr, Diagnostic> {
97	    // Try to statically evaluate all of the function arguments.
98	    let mut args = Vec::with_capacity(call.args.len());
99	    for arg in &call.args {
100	      match self.eval(&*arg.expr) {
101	        Ok(val) => {
102	          if arg.spread.is_none() {
103	            args.push(val);
104	          } else if let JsValue::Array(val) = val {
105	            args.extend(val);
106	          } else {
107	            return Err(self.create_diagnostic(call.span));
108	          }
109	        }
110	        Err(span) => {
111	          return Err(self.create_diagnostic(span));
112	        }
113	      }
114	    }
115	
116	    // If that was successful, call the function callback (on the JS thread).
117	    let loc = SourceLocation::from(self.source_map, call.span);
118	    match (self.callback)(src, export, args, loc.clone()) {
119	      Ok(val) => Ok(self.value_to_expr(val)?),
120	      Err(err) => Err(Diagnostic {
121	        message: format!("Error evaluating macro: {}", err),
122	        code_highlights: Some(vec![CodeHighlight { message: None, loc }]),
123	        hints: None,
124	        show_environment: false,
125	        severity: crate::utils::DiagnosticSeverity::Error,
126	        documentation_url: None,
127	      }),
128	    }
129	  }
130	
131	  fn create_diagnostic(&self, span: Span) -> Diagnostic {
132	    Diagnostic {
133	      message: "Could not statically evaluate macro argument".into(),
134	      code_highlights: Some(vec![CodeHighlight {
135	        message: None,
136	        loc: SourceLocation::from(self.source_map, span),
137	      }]),
138	      hints: None,
139	      show_environment: false,
140	      severity: crate::utils::DiagnosticSeverity::Error,
141	      documentation_url: None,
142	    }
143	  }
144	}
