216	        tx.send(Ok(res)).expect("send failure");
217	        ctx.env.get_undefined()
218	      })?;
219	      let eb = env.create_function_from_closure("error_callback", move |ctx| {
220	        let res = ctx.get::<JsUnknown>(0)?;
221	        let message = match napi_to_js_value(res, env)? {
222	          JsValue::String(s) => s,
223	          _ => "Unknown error".into(),
224	        };
225	        tx2.send(Err(message)).expect("send failure");
226	        ctx.env.get_undefined()
227	      })?;
228	      then.call(Some(&result), &[cb, eb])?;
229	    } else {
230	      tx.send(Ok(napi_to_js_value(result, env)?))
231	        .expect("send failure");
232	    }
