143	  fn napi_to_js_value(value: napi::JsUnknown, env: Env) -> napi::Result<JsValue> {
144	    match value.get_type()? {
145	      ValueType::Undefined => Ok(JsValue::Undefined),
146	      ValueType::Null => Ok(JsValue::Null),
147	      ValueType::Number => Ok(JsValue::Number(
148	        unsafe { value.cast::<JsNumber>() }.get_double()?,
149	      )),
150	      ValueType::Boolean => Ok(JsValue::Bool(
151	        unsafe { value.cast::<JsBoolean>() }.get_value()?,
152	      )),
153	      ValueType::String => Ok(JsValue::String(
154	        unsafe { value.cast::<JsString>() }
155	          .into_utf8()?
156	          .into_owned()?,
157	      )),
158	      ValueType::Object => {
159	        let obj = unsafe { value.cast::<JsObject>() };
160	        if obj.is_array()? {
161	          let len = obj.get_array_length()?;
162	          let mut arr = Vec::with_capacity(len as usize);
163	          for i in 0..len {
164	            let elem = napi_to_js_value(obj.get_element(i)?, env)?;
165	            arr.push(elem);
166	          }
167	          Ok(JsValue::Array(arr))
168	        } else {
169	          let regexp_class: JsFunction = env.get_global()?.get_named_property("RegExp")?;
170	          if obj.instanceof(regexp_class)? {
171	            let source: JsString = obj.get_named_property("source")?;
172	            let flags: JsString = obj.get_named_property("flags")?;
173	            return Ok(JsValue::Regex {
174	              source: source.into_utf8()?.into_owned()?,
175	              flags: flags.into_utf8()?.into_owned()?,
176	            });
177	          }
178	
179	          let names = obj.get_property_names()?;
180	          let len = names.get_array_length()?;
181	          let mut props = IndexMap::with_capacity(len as usize);
182	          for i in 0..len {
183	            let prop = names.get_element::<JsString>(i)?;
184	            let name = prop.into_utf8()?.into_owned()?;
185	            let value = napi_to_js_value(obj.get_property(prop)?, env)?;
186	            props.insert(name, value);
187	          }
188	          Ok(JsValue::Object(props))
189	        }
190	      }
191	      ValueType::Function => {
192	        let f = unsafe { value.cast::<JsFunction>() };
193	        let source = f.coerce_to_string()?.into_utf8()?.into_owned()?;
194	        Ok(JsValue::Function(source))
195	      }
196	      ValueType::Symbol | ValueType::External | ValueType::Unknown => Err(napi::Error::new(
197	        napi::Status::GenericFailure,
198	        "Could not convert value returned from macro to AST.",
199	      )),
200	    }

